//! UV theory fraction comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_uv_phi.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::ljs::{
    calc_uv_wca, ljs_b2, uv_a1_b2, uv_a1_u, uv_delta_b2_overall, uv_hard_sphere_b2, uv_phi,
    uv_phi_temp, uv_q_of_temperature,
};

const ATOL: f64 = 1.0e-14;
const RTOL: f64 = 1.0e-12;

#[test]
fn uv_fractions_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/uv_phi.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let eps_divk: f64 = parts[0].parse().unwrap();
        let temperature: f64 = parts[1].parse().unwrap();
        let rho: f64 = parts[2].parse().unwrap();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let native = uv_phi(eps_divk, temperature, rho);
        let native = [native.0, native.1, native.2, native.3, native.4, native.5];
        assert_eq!(native.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 5);
}

