#[test]
fn uv_virials_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/uv_virials.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let eps_divk: f64 = parts[0].parse().unwrap();
        let temperature: f64 = parts[1].parse().unwrap();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let (q, q_t, q_tt) = uv_q_of_temperature(eps_divk, temperature);
        let (hs2, hs2_t, hs2_tt) = uv_hard_sphere_b2(eps_divk, temperature);
        let (ljs2, ljs2_t, ljs2_tt) = ljs_b2(eps_divk, temperature);
        let native = [q, q_t, q_tt, hs2, hs2_t, hs2_tt, ljs2, ljs2_t, ljs2_tt];
        assert_eq!(native.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 4);
}

#[test]
fn uv_virial_difference_matches_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/uv_virial_difference.csv")
        .lines()
        .skip(1)
    {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let sigma: f64 = parts[0].parse().unwrap();
        let eps_divk: f64 = parts[1].parse().unwrap();
        let temperature: f64 = parts[2].parse().unwrap();
        let rho: f64 = parts[3].parse().unwrap();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let (diameter, diameter_t, diameter_tt) =
            thermopack_rs::hardsphere_wca::hard_sphere_diameter(sigma, eps_divk, temperature);
        let difference = uv_delta_b2_overall(
            sigma,
            eps_divk,
            temperature,
            diameter,
            diameter_t,
            diameter_tt,
            rho,
        );
        let term = calc_uv_wca(
            sigma,
            eps_divk,
            rho,
            temperature,
            diameter,
            diameter_t,
            diameter_tt,
            true,
            false,
        );
        let native = [
            difference.0,
            difference.1,
            difference.2,
            difference.3,
            difference.4,
            difference.5,
            term.0,
            term.1,
            term.2,
            term.3,
            term.4,
            term.5,
        ];
        assert_eq!(native.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= 1.0e-14 + 1.0e-11 * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 5);
}

#[test]
fn the_temperature_dependent_fraction_carries_the_derivatives() {
    // The temperature dependent form of the source adds the derivatives with
    // respect to the temperature, and its fraction agrees with the plain form
    // at the reduced density of the source.
    let eps_divk = 124.0;
    let temperature = 200.0;
    let rho = 0.8;
    let (value, value_r, value_t, value_rr, value_tt, value_rt) =
        uv_phi_temp(eps_divk, temperature, rho);
    assert!(value.is_finite() && value_r.is_finite());
    assert!(value_rr.is_finite() && value_tt.is_finite() && value_rt.is_finite());
    // The plain form of the source does not depend on the temperature.
    let (_, plain_r, plain_t, _, plain_tt, plain_rt) = uv_phi(eps_divk, temperature, rho);
    assert!((plain_t - 0.0).abs() < 1.0e-30);
    assert!((plain_tt - 0.0).abs() < 1.0e-30);
    assert!((plain_rt - 0.0).abs() < 1.0e-30);
    assert!(value_t.abs() > 0.0);
    assert!(plain_r != value_r);
}
